     1 | /**
     2 |  * Rule-based "Feels Like" Reasoning Generator
     3 |  * Explains WHY the apparent temperature differs from the actual temperature.
     4 |  */
     5 | 
     6 | export const getFeelsLikeReasoning = (tempC, apparentTempC, humidity, windKmH, uvIndex = 0) => {
     7 |   const diff = apparentTempC - tempC;
     8 | 
     9 |   if (Math.abs(diff) < 1.0) {
    10 |     if (humidity > 70) {
    11 |       return "Feels accurate, with high humidity keeping conditions pleasant.";
    12 |     }
    13 |     if (windKmH > 20) {
    14 |       return "Feels true to actual temperature despite a slight breeze.";
    15 |     }
    16 |     return "Feels identical to the actual temperature.";
    17 |   }
    18 | 
    19 |   // Warmer than actual temp
    20 |   if (diff >= 1.0) {
    21 |     if (humidity >= 75) {
    22 |       return `Feels ${Math.round(diff)}° warmer due to high humidity (${humidity}%) trapping body heat.`;
    23 |     }
    24 |     if (uvIndex >= 7) {
    25 |       return `Feels ${Math.round(diff)}° warmer under intense direct solar radiation (UV ${uvIndex}).`;
    26 |     }
    27 |     return `Feels ${Math.round(diff)}° warmer due to moisture and solar heat absorption.`;
    28 |   }
    29 | 
    30 |   // Colder than actual temp
    31 |   if (diff <= -1.0) {
    32 |     const absDiff = Math.abs(Math.round(diff));
    33 |     if (windKmH >= 25) {
    34 |       return `Feels ${absDiff}° colder due to strong wind chill from ${Math.round(windKmH)} km/h gusts.`;
    35 |     }
    36 |     if (windKmH >= 12) {
    37 |       return `Feels ${absDiff}° cooler due to a brisk ${Math.round(windKmH)} km/h wind.`;
    38 |     }
    39 |     if (tempC < 10) {
    40 |       return `Feels ${absDiff}° colder due to frigid ambient air moisture.`;
    41 |     }
    42 |     return `Feels ${absDiff}° cooler due to wind movement and lower humidity.`;
    43 |   }
    44 | 
    45 |   return "Feels consistent with local atmospheric conditions.";
    46 | };
